-- Where is the WAL right now, and how far behind is the last checkpoint?
SELECT pg_current_wal_lsn();
SELECT checkpoint_lsn, redo_lsn FROM pg_control_checkpoint();

-- Trade a tiny bit of durability for speed on low-value writes only:
SET LOCAL synchronous_commit = off;  -- may lose the last few ms of commits on crash, never corrupts

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE owner = 'alice';
UPDATE accounts SET balance = balance + 100 WHERE owner = 'bob';
COMMIT;   -- both happen, or (on any error / crash before this line) neither does

-- Consistency is enforced by the schema, not by hope:
ALTER TABLE accounts ADD CONSTRAINT no_overdraft CHECK (balance >= 0);

-- Each doctor's transaction
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM shifts WHERE day = '2026-10-11' AND on_call;   -- sees 2
UPDATE shifts SET on_call = false WHERE day = '2026-10-11' AND doctor = 'alice';
COMMIT;  -- one of the two concurrent commits gets SQLSTATE 40001 → retry

-- Alternative without SERIALIZABLE: lock the rows you base the decision on
SELECT * FROM shifts WHERE day = '2026-10-11' AND on_call FOR UPDATE;

EXPLAIN (ANALYZE, BUFFERS)
SELECT * FROM orders WHERE customer_id = 7781 ORDER BY created_at DESC LIMIT 20;
--  Limit → Sort → Seq Scan on orders  (rows removed by filter: 49,999,688)  4012 ms

CREATE INDEX CONCURRENTLY idx_orders_customer_recent
  ON orders (customer_id, created_at DESC);

--  Limit → Index Scan using idx_orders_customer_recent   (actual rows=20)  0.09 ms

CREATE TABLE events (
  id bigint GENERATED ALWAYS AS IDENTITY,
  tenant_id int NOT NULL,
  created_at timestamptz NOT NULL,
  payload jsonb
) PARTITION BY RANGE (created_at);

CREATE TABLE events_2026_10 PARTITION OF events
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

-- 90-day retention: detach then drop, no DELETE, no bloat
ALTER TABLE events DETACH PARTITION events_2026_06 CONCURRENTLY;
DROP TABLE events_2026_06;

SET lock_timeout = '3s';            -- give up fast instead of blocking the app
ALTER TABLE users ADD COLUMN full_name text;

-- backfill in batches (run in a loop until 0 rows updated)
UPDATE users SET full_name = name
WHERE id IN (SELECT id FROM users WHERE full_name IS NULL AND name IS NOT NULL LIMIT 5000);

-- constraints online: add without scanning, validate without blocking writes
ALTER TABLE users ADD CONSTRAINT full_name_not_null CHECK (full_name IS NOT NULL) NOT VALID;
ALTER TABLE users VALIDATE CONSTRAINT full_name_not_null;
